<?php $video = $video ?? []; ?>
<form class="editor-form" method="post" enctype="multipart/form-data" action="<?= !empty($video['id']) ? url('/admin/videos/'.$video['id']) : url('/admin/videos') ?>"><?= csrf_field() ?>
<?php if ($error): ?><div class="form-error full"><?= e($error) ?></div><?php endif; ?>
<section class="form-main admin-panel"><h2>Contenido del video</h2><label>Título *<input name="title" required maxlength="180" value="<?= e($video['title'] ?? '') ?>" placeholder="Título que aparecerá en Pulso Angelino TV"></label><label>Descripción</label><div class="rich-editor" data-rich-editor><div class="rich-toolbar" role="toolbar" aria-label="Formato de texto"><button type="button" data-command="bold"><b>N</b></button><button type="button" data-command="italic"><i>K</i></button><button type="button" data-command="underline"><u>S</u></button><button type="button" data-command="formatBlock" data-value="h2">Título</button><button type="button" data-command="insertUnorderedList">• Lista</button><button type="button" data-command="createLink">Enlace</button><button type="button" data-command="removeFormat">Limpiar</button></div><div class="rich-canvas" contenteditable="true"><?= $video['description'] ?? '' ?></div><textarea class="rich-source" name="description" hidden><?= e($video['description'] ?? '') ?></textarea></div><label>URL del video *<input type="url" name="video_url" required maxlength="1000" value="<?= e($video['video_url'] ?? '') ?>" placeholder="https://youtube.com/watch?v=... o URL de otro medio"></label><span class="hint">Compatible con YouTube, Vimeo, archivos MP4/WebM y enlaces a otras plataformas.</span></section>
<aside><section class="admin-panel"><h2>Clasificación</h2><label>Comuna<select name="commune"><?php foreach (App\Models\Video::COMMUNES as $commune): ?><option <?= ($video['commune'] ?? 'Los Ángeles') === $commune ? 'selected' : '' ?>><?= e($commune) ?></option><?php endforeach; ?></select></label><label>Tipo de contenido<select name="format"><?php foreach (App\Models\Video::FORMATS as $format): ?><option <?= ($video['format'] ?? 'Reportajes') === $format ? 'selected' : '' ?>><?= e($format) ?></option><?php endforeach; ?></select></label></section><section class="admin-panel"><h2>Publicación</h2><label>Estado<select name="status"><option value="draft" <?= ($video['status'] ?? '') === 'draft' ? 'selected' : '' ?>>Borrador</option><option value="published" <?= ($video['status'] ?? 'published') === 'published' ? 'selected' : '' ?>>Publicado</option></select></label><label>Fecha y hora<input type="datetime-local" name="published_at" value="<?= e(isset($video['published_at']) ? date('Y-m-d\TH:i', strtotime($video['published_at'])) : date('Y-m-d\TH:i')) ?>"></label><button class="primary-button">Guardar video →</button></section><section class="admin-panel"><h2>Imagen de portada obligatoria</h2><?php if (!empty($video['cover_image'])): ?><img class="video-cover-preview" src="<?= e(post_image($video['cover_image'])) ?>" alt="Portada actual"><?php endif; ?><label>Subir imagen<input type="file" name="upload" accept="image/jpeg,image/png,image/webp"></label><span class="hint">JPG, PNG o WebP. Máximo 5 MB.</span><label>o importar desde una URL<input type="url" name="cover_image" value="<?= e($video['cover_image'] ?? '') ?>" placeholder="https://..."></label><span class="hint">La portada externa se copiará al servidor y dejará de depender del enlace original.</span></section></aside>
